xpath.script:
(function() {
    try {
        var tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
        if (tz) {
            var match = document.cookie.match(/(?:^|;\s*)user_tz=([^;]+)/);
            var currentTz = match ? decodeURIComponent(match[1]) : null;
            if (currentTz !== tz) {
                document.cookie = "user_tz=" + encodeURIComponent(tz) + "; path=/; max-age=31536000; SameSite=Lax";
                if (!sessionStorage.getItem('jandalah_tz_synced')) {
                    sessionStorage.setItem('jandalah_tz_synced', '1');
                    window.location.reload();
                }
            }
        }
    } catch(e) {}
})();

t.script:
// 1. Live Saudi Clock
function updateClock() {
    const now = new Date();
    const options = { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true };
    const clockEl = document.getElementById('ess_live_clock');
    if (clockEl) {
        clockEl.innerText = now.toLocaleTimeString('ar-SA', options);
    }
}
setInterval(updateClock, 1000);
updateClock();

// 2. Service Worker Registration
if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('/jandalah/sw.js').then(function() {
        console.log('Jandalah PWA ServiceWorker Registered');
    }).catch(function(err) {
        console.log('SW registration error:', err);
    });
}

// 3. Smart Adaptive PWA Detection
let deferredPrompt = null;
const ua = navigator.userAgent || navigator.vendor || window.opera;
const isIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
const isCriOS = isIOS && /CriOS/.test(ua);
const isSafari = isIOS && /Safari/.test(ua) && !isCriOS;
const isInApp = /FBAN|FBAV|Instagram|WhatsApp|Twitter|Snapchat/i.test(ua);
const isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;

document.addEventListener('DOMContentLoaded', function() {
    if (isStandalone) {
        return; // Already installed as PWA!
    }

    const pwaContainer = document.getElementById('pwa_smart_container');
    if (!pwaContainer) return;

    if (sessionStorage.getItem('jandalah_pwa_dismissed') === '1') {
        return;
    }

    if (isInApp) {
        pwaContainer.classList.remove('d-none');
        document.getElementById('pwa_inapp_box')?.classList.remove('d-none');
    } else if (isIOS) {
        pwaContainer.classList.remove('d-none');
        if (isSafari) {
            document.getElementById('pwa_ios_safari_box')?.classList.remove('d-none');
        } else {
            document.getElementById('pwa_ios_chrome_box')?.classList.remove('d-none');
        }
    }
});

window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    const pwaContainer = document.getElementById('pwa_smart_container');
    if (pwaContainer && sessionStorage.getItem('jandalah_pwa_dismissed') !== '1') {
        pwaContainer.classList.remove('d-none');
        document.getElementById('pwa_android_box')?.classList.remove('d-none');
    }
});

function installPWA() {
    if (deferredPrompt) {
        deferredPrompt.prompt();
        deferredPrompt.userChoice.then((choiceResult) => {
            if (choiceResult.outcome === 'accepted') {
                dismissPwa();
            }
            deferredPrompt = null;
        });
    }
}

function dismissPwa() {
    const container = document.getElementById('pwa_smart_container');
    if (container) container.classList.add('d-none');
    sessionStorage.setItem('jandalah_pwa_dismissed', '1');
}

function copyPortalUrl() {
    const url = window.location.origin + '/my';
    navigator.clipboard.writeText(url).then(() => {
        const f1 = document.getElementById('copy_feedback_chrome');
        const f2 = document.getElementById('copy_feedback_inapp');
        if (f1) f1.classList.remove('d-none');
        if (f2) f2.classList.remove('d-none');
    });
}

// 4. GPS Geolocation and 1-Tap Toggle
function toggleAttendance() {
    const btn = document.getElementById('btn_toggle_attendance');
    const feedback = document.getElementById('attendance_feedback');
    btn.disabled = true;
    feedback.className = 'mt-2 small fw-bold text-info text-center';
    feedback.innerHTML = ' جاري تحديد الموقع الجغرافي (GPS)...';

    if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition(
            function(pos) {
                sendAttendance(pos.coords.latitude, pos.coords.longitude);
            },
            function(err) {
                console.warn("GPS error: " + err.message);
                btn.disabled = false;
                feedback.className = 'mt-2 small fw-bold text-danger text-center';
                feedback.innerHTML = ' يرجى تفعيل خدمة تحديد الموقع (GPS) ومنح الصلاحية للمتصفح لإتمام البصمة.';
            },
            { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 }
        );
    } else {
        btn.disabled = false;
        feedback.className = 'mt-2 small fw-bold text-danger text-center';
        feedback.innerHTML = ' جهازك أو متصفحك لا يدعم تحديد الموقع (GPS).';
    }
}

function sendAttendance(lat, lon) {
    const btn = document.getElementById('btn_toggle_attendance');
    const feedback = document.getElementById('attendance_feedback');
    feedback.innerHTML = ' جاري حفظ تسجيل الحضور في النظام...';

    fetch('/my/attendance/toggle', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            params: {
                latitude: lat,
                longitude: lon,
                browser: navigator.userAgent,
                tz: Intl.DateTimeFormat().resolvedOptions().timeZone
            }
        })
    })
    .then(res => res.json())
    .then(data => {
        btn.disabled = false;
        if (data.result && data.result.status === 'success') {
            feedback.className = 'mt-2 small fw-bold text-success text-center';
            feedback.innerHTML = ' ' + data.result.message;
            setTimeout(() => { window.location.reload(); }, 1500);
        } else {
            feedback.className = 'mt-2 small fw-bold text-danger text-center';
            feedback.innerHTML = ' ' + (data.result ? data.result.message : 'حدث خطأ في التسجيل');
        }
    })
    .catch(err => {
        btn.disabled = false;
        feedback.className = 'mt-2 small fw-bold text-danger text-center';
        feedback.innerHTML = ' تعذر الاتصال بالسيرفر. يرجى المحاولة ثانية.';
    });
}

div.script:
document.addEventListener('DOMContentLoaded', function() {
    var sel = document.querySelector('select[name="holiday_status_id"]');
    if (sel) {
        sel.addEventListener('change', function() {
            var txt = sel.options[sel.selectedIndex].text;
            var alertBox = document.getElementById('sick_leave_alert');
            if (alertBox) {
                if (txt.indexOf('مرض') !== -1 || txt.toLowerCase().indexOf('sick') !== -1) {
                    alertBox.classList.remove('d-none');
                } else {
                    alertBox.classList.add('d-none');
                }
            }
        });
    }
});

function openRefuseModal(btn) {
    try {
        var leaveId = btn.getAttribute('data-leave-id') || '';
        var empName = btn.getAttribute('data-emp-name') || '';
        var leaveType = btn.getAttribute('data-leave-type') || '';
        var leaveDays = btn.getAttribute('data-leave-days') || '';

        var idInput = document.getElementById('modal_refuse_leave_id');
        if (idInput) idInput.value = leaveId;

        var nameEl = document.getElementById('modal_refuse_emp_name');
        if (nameEl) nameEl.innerText = empName;

        var typeEl = document.getElementById('modal_refuse_leave_type');
        if (typeEl) typeEl.innerText = leaveType;

        var daysEl = document.getElementById('modal_refuse_leave_days');
        if (daysEl) daysEl.innerText = leaveDays + ' يوم';

        var reasonInput = document.getElementById('modal_refusal_reason');
        if (reasonInput) reasonInput.value = '';

        var modalEl = document.getElementById('refuseLeaveModal');
        if (!modalEl) return;

        // 1. Try native Bootstrap 5
        if (typeof window.bootstrap !== 'undefined' && window.bootstrap.Modal) {
            try {
                var modal = window.bootstrap.Modal.getInstance(modalEl) || new window.bootstrap.Modal(modalEl);
                modal.show();
            } catch(e) {}
        }
        // 2. Try jQuery / Bootstrap 4
        else if (typeof window.$ !== 'undefined' && typeof window.$.fn.modal !== 'undefined') {
            try {
                window.$(modalEl).modal('show');
            } catch(e) {}
        }

        // 3. Robust fallback: Force modal visibility if not displayed yet
        setTimeout(function() {
            if (modalEl.style.display !== 'block') {
                modalEl.classList.add('show');
                modalEl.style.display = 'block';
                modalEl.style.backgroundColor = 'rgba(0,0,0,0.5)';
                modalEl.removeAttribute('aria-hidden');
                modalEl.setAttribute('aria-modal', 'true');
                document.body.classList.add('modal-open');
            }
        }, 50);
    } catch (err) {
        console.error('openRefuseModal error:', err);
    }
}

function closeRefuseModal() {
    try {
        var modalEl = document.getElementById('refuseLeaveModal');
        if (!modalEl) return;

        if (typeof window.bootstrap !== 'undefined' && window.bootstrap.Modal) {
            try {
                var modal = window.bootstrap.Modal.getInstance(modalEl);
                if (modal) modal.hide();
            } catch(e) {}
        }
        if (typeof window.$ !== 'undefined' && typeof window.$.fn.modal !== 'undefined') {
            try {
                window.$(modalEl).modal('hide');
            } catch(e) {}
        }

        modalEl.classList.remove('show');
        modalEl.style.display = 'none';
        modalEl.style.backgroundColor = '';
        modalEl.setAttribute('aria-hidden', 'true');
        modalEl.removeAttribute('aria-modal');
        document.body.classList.remove('modal-open');
    } catch (err) {
        console.error('closeRefuseModal error:', err);
    }
}

function setRefusalReason(text) {
    var ta = document.getElementById('modal_refusal_reason');
    if (ta) {
        ta.value = text;
        ta.focus();
    }
}

// Close modal when clicking outside modal dialog
document.addEventListener('DOMContentLoaded', function() {
    var modalEl = document.getElementById('refuseLeaveModal');
    if (modalEl) {
        modalEl.addEventListener('click', function(e) {
            if (e.target === modalEl) {
                closeRefuseModal();
            }
        });
    }
});

function openPenaltyModal(btn) {
    var pId = btn.getAttribute('data-penalty-id');
    document.getElementById('modal_penalty_id').value = pId;
}

function captureTempLocation() {
    var status = document.getElementById('gps_status_text');
    status.innerText = 'جارٍ تحديد موقعك عبر GPS...';
    if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition(
            function(pos) {
                document.getElementById('modal_temp_lat').value = pos.coords.latitude;
                document.getElementById('modal_temp_lon').value = pos.coords.longitude;
                status.innerHTML = ' تم التقاط الإحداثيات بنجاح (' + pos.coords.latitude.toFixed(4) + ', ' + pos.coords.longitude.toFixed(4) + ')';
            },
            function(err) {
                status.innerText = 'تعذر التقاط الموقع بدقة، سيتم المتابعة بالاسم.';
            },
            { enableHighAccuracy: true, timeout: 6000 }
        );
    }
}
